# Databricks notebook source
# MAGIC %md
# MAGIC # 01 - Generate raw auction logs (synthetic)
# MAGIC
# MAGIC Writes one gzip JSON-lines file per hour into the landing volume, mimicking the log rotation of
# MAGIC Halyard's bidder fleet. Re-running only writes days that are missing, so the job can run daily
# MAGIC and Auto Loader picks up just the new files.
# MAGIC
# MAGIC All data is synthetic, generated by `src/halyard_sim.py`. No customer data is used.

# COMMAND ----------

dbutils.widgets.text("catalog", "cmegdemos_catalog")
dbutils.widgets.text("schema", "ssp_traffic_shaping")
dbutils.widgets.text("days", "14")
dbutils.widgets.text("auctions_per_day", "40000")
catalog = dbutils.widgets.get("catalog")
schema = dbutils.widgets.get("schema")
days = int(dbutils.widgets.get("days"))
auctions_per_day = int(dbutils.widgets.get("auctions_per_day"))

# COMMAND ----------

import datetime as dt
import os
import sys

import pandas as pd

sys.path.append(os.path.abspath(".."))
import halyard_sim as hs

landing = f"/Volumes/{catalog}/{schema}/raw_landing"
out_dir = f"{landing}/auctions"
publishers = pd.read_csv(f"{landing}/reference/publishers.csv")
os.makedirs(out_dir, exist_ok=True)
existing = set(os.listdir(out_dir))

today = dt.date.today()
written, skipped, n_records = 0, 0, 0
for k in range(days, 0, -1):
    day = today - dt.timedelta(days=k)
    if any(f.startswith(f"auctions_{day:%Y-%m-%d}") for f in existing):
        skipped += 1
        continue
    recs = hs.simulate_day(day, auctions_per_day, publishers, seed=int(day.strftime("%Y%m%d")))
    files = hs.write_day(recs, out_dir, day)
    written += 1
    n_records += len(recs)
    print(f"{day}: {len(recs):,} auction records -> {len(files)} hourly files")

print(f"\nDays written: {written}, already present: {skipped}, new auction records: {n_records:,}")
print(f"Files in landing: {len(os.listdir(out_dir))}")

# COMMAND ----------

# MAGIC %md
# MAGIC ### Sample raw record (what the bidder fleet emits)

# COMMAND ----------

import gzip, json
sample_file = sorted(os.listdir(out_dir))[-1]
with gzip.open(f"{out_dir}/{sample_file}", "rt") as f:
    print(json.dumps(json.loads(f.readline()), indent=2))
